def kthDistinctSubsequence(s, k):
    n = len(s)
    CAP = 2 * 10 ** 9
    nxt = [None] * (n + 1)
    nxt[n] = [-1] * 26
    for i in range(n - 1, -1, -1):
        row = nxt[i + 1][:]
        row[ord(s[i]) - 97] = i
        nxt[i] = row
    f = [0] * (n + 1)
    f[n] = 1
    for i in range(n - 1, -1, -1):
        tot = 1
        for j in nxt[i]:
            if j >= 0:
                tot += f[j + 1]
        f[i] = min(tot, CAP)
    pos = 0
    res = []
    while True:
        for c in range(26):
            j = nxt[pos][c]
            if j < 0:
                continue
            cnt = f[j + 1]
            if k <= cnt:
                res.append(chr(97 + c))
                if k == 1:
                    return "".join(res)
                k -= 1
                pos = j + 1
                break
            k -= cnt
        else:
            return "-"
